// Utility helpers: format, inspect, inherits, promisify, deprecate, type checks, etc.

import { Buffer } from "./buffer";

/**
 * Options accepted by `inspect` — and therefore by `formatWithOptions`, which threads them through.
 *
 * Deliberately the full Node shape rather than the two keys this implementation reads. The narrow
 * `{ depth?, colors? }` it replaced made `formatWithOptions` a lie at the type level: callers pass
 * whatever Node accepts (`debug` passes its whole `inspectOpts` bag), so a signature that rejects
 * them would either fail to compile or force a cast at every call site.
 *
 * ⚠️ Only `depth` is honoured today; the rest are accepted and ignored. That is a real gap, but a
 * documented one — the alternative was to keep a type that could not express what callers send.
 */
export interface InspectOptions {
  depth?: number | null;
  colors?: boolean;
  showHidden?: boolean;
  showProxy?: boolean;
  maxArrayLength?: number | null;
  maxStringLength?: number | null;
  breakLength?: number;
  compact?: boolean | number;
  sorted?: boolean | ((a: string, b: string) => number);
  getters?: boolean | "get" | "set";
  numericSeparator?: boolean;
  customInspect?: boolean;
}

/**
 * The one specifier parser, shared by `format` and `formatWithOptions`.
 *
 * 🔴 Shared on purpose. The two differ ONLY in which inspect options reach `%o`/`%O` and the trailing
 * arguments, so a second copy would drift on the next `%`-specifier fix and the two would silently
 * disagree about the same template.
 *
 * Semantics are byte-for-byte what `format` already did — this extraction threads options and changes
 * nothing else. (Node's `%d` is `Number()` where this is `parseInt`; that pre-existing deviation is
 * left alone deliberately, because changing `format`'s output is not this fix and the runtime's
 * loggers already depend on it.)
 */
function formatImpl(
  inspectOptions: InspectOptions,
  template: unknown,
  values: unknown[],
): string {
  if (typeof template !== "string") {
    // non-string first arg: inspect all args
    return [template, ...values]
      .map((v) => (typeof v === "string" ? v : inspect(v, inspectOptions)))
      .join(" ");
  }

  let idx = 0;
  let result = template.replace(/%[sdjifoO%]/g, (token) => {
    if (token === "%%") return "%";
    if (idx >= values.length) return token;

    const val = values[idx++];
    switch (token) {
      case "%s":
        return String(val);
      case "%d":
      case "%i":
        return String(parseInt(String(val), 10));
      case "%f":
        return String(parseFloat(String(val)));
      case "%j":
        try {
          return JSON.stringify(val);
        } catch {
          return "[Circular]";
        }
      case "%o":
      case "%O":
        return inspect(val, inspectOptions);
      default:
        return token;
    }
  });

  // append extra args beyond what format specifiers consumed (matches Node.js)
  while (idx < values.length) {
    const v = values[idx++];
    result += " " + (typeof v === "string" ? v : inspect(v, inspectOptions));
  }

  return result;
}

export function format(template: unknown, ...values: unknown[]): string {
  return formatImpl({}, template, values);
}

/**
 * `util.formatWithOptions(inspectOptions, format[, ...args])` — Node 10+.
 *
 * 🔴 This is the symbol whose absence broke EVERY published game. `debug` — a transitive dependency of
 * essentially every build tool — logs through `util.formatWithOptions(exports.inspectOpts, ...args)`,
 * so `vite build` died with `TypeError: formatWithOptions is not a function` before emitting anything.
 * Dev never reached that logger, which is why only publishing was broken.
 *
 * ⚠️ Node throws `ERR_INVALID_ARG_TYPE` when `inspectOptions` is not an object. This is deliberately
 * lenient instead: a bad options bag degrades to `{}` rather than throwing, because the failure mode
 * of throwing here is exactly the one being fixed — a build that dies inside a logger.
 */
export function formatWithOptions(
  inspectOptions: InspectOptions,
  template?: unknown,
  ...values: unknown[]
): string {
  const opts =
    typeof inspectOptions === "object" && inspectOptions !== null
      ? inspectOptions
      : {};
  return formatImpl(opts, template, values);
}

export function inspect(target: unknown, opts?: InspectOptions): string {
  const visited = new WeakSet();
  // `depth: null` means unlimited in Node; `?? 2` alone would quietly clamp it to the default.
  const maxDepth =
    opts?.depth === null ? Infinity : (opts?.depth ?? 2);

  function render(val: unknown, level: number): string {
    if (val === null) return "null";
    if (val === undefined) return "undefined";

    const kind = typeof val;
    if (kind === "string") return `'${val}'`;
    if (kind === "number" || kind === "boolean") return String(val);
    if (kind === "bigint") return `${val as bigint}n`;
    if (kind === "symbol") return (val as symbol).toString();
    if (kind === "function") {
      const fname = (val as Function).name || "anonymous";
      return `[Function: ${fname}]`;
    }
    if (kind !== "object") return String(val);

    if (visited.has(val as object)) return "[Circular]";
    visited.add(val as object);

    if (level > maxDepth) {
      return Array.isArray(val) ? "[Array]" : "[Object]";
    }

    if (Array.isArray(val)) {
      if (val.length === 0) return "[]";
      const items = val.map((item) => render(item, level + 1));
      return `[ ${items.join(", ")} ]`;
    }

    if (val instanceof Date) return val.toISOString();
    if (val instanceof RegExp) return val.toString();
    if (val instanceof Error) return `${val.name}: ${val.message}`;

    if (val instanceof Map) {
      const pairs = [...val.entries()].map(
        ([k, v]) => `${render(k, level + 1)} => ${render(v, level + 1)}`,
      );
      return `Map(${val.size}) { ${pairs.join(", ")} }`;
    }

    if (val instanceof Set) {
      const items = [...val].map((v) => render(v, level + 1));
      return `Set(${val.size}) { ${items.join(", ")} }`;
    }

    const keys = Object.keys(val as object);
    if (keys.length === 0) return "{}";
    const fields = keys.map((k) => {
      const v = (val as Record<string, unknown>)[k];
      return `${k}: ${render(v, level + 1)}`;
    });
    return `{ ${fields.join(", ")} }`;
  }

  return render(target, 0);
}

export function inherits(child: Function, parent: Function): void {
  if (child === undefined || child === null) {
    throw new TypeError("inherits: child constructor must be provided");
  }
  if (parent === undefined || parent === null) return;
  if (parent.prototype === undefined) return;
  (child as any).super_ = parent;
  Object.setPrototypeOf(child.prototype, parent.prototype);
}

// deprecated, equivalent to Object.assign
export function _extend(target: any, source: any): any {
  if (source == null) return target;
  const keys = Object.keys(source);
  for (let i = 0; i < keys.length; i++) {
    target[keys[i]] = source[keys[i]];
  }
  return target;
}

export function deprecate<T extends Function>(
  fn: T,
  message: string,
  code?: string,
): T {
  let alerted = false;
  const wrapper = function (this: unknown, ...args: unknown[]) {
    if (!alerted) {
      console.warn(`DeprecationWarning: ${message}${code ? ` (${code})` : ""}`);
      alerted = true;
    }
    return fn.apply(this, args);
  };
  return wrapper as unknown as T;
}

export function promisify<T>(
  fn: (...args: any[]) => void,
): (...args: any[]) => Promise<T> {
  return (...args: any[]) =>
    new Promise((ok, fail) => {
      fn(...args, (err: Error | null, result: T) => {
        if (err) fail(err);
        else ok(result);
      });
    });
}

export function callbackify<T>(
  fn: (...args: any[]) => Promise<T>,
): (...args: any[]) => void {
  return (...args: any[]) => {
    const cb = args.pop() as (err: Error | null, result: T) => void;
    fn(...args)
      .then((result) => cb(null, result))
      .catch((err) => cb(err, undefined as unknown as T));
  };
}

export function isDeepStrictEqual(a: unknown, b: unknown): boolean {
  return deepStrictEqualInner(a, b, new WeakMap());
}

function deepStrictEqualInner(
  a: unknown,
  b: unknown,
  seen: WeakMap<object, WeakSet<object>>,
): boolean {
  if (Object.is(a, b)) return true;
  if (a === null || b === null) return false;
  if (typeof a !== typeof b) return false;

  if (typeof a !== "object" || typeof b !== "object") {
    return false;
  }

  const objA = a as object;
  const objB = b as object;

  const seenB = seen.get(objA);
  if (seenB?.has(objB)) return true;
  if (!seenB) seen.set(objA, new WeakSet([objB]));
  else seenB.add(objB);

  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }
  if (a instanceof RegExp && b instanceof RegExp) {
    return a.source === b.source && a.flags === b.flags;
  }
  if (a instanceof Error && b instanceof Error) {
    return (
      a.name === b.name &&
      a.message === b.message &&
      deepStrictEqualInner(a.cause, b.cause, seen)
    );
  }

  if (ArrayBuffer.isView(a) && ArrayBuffer.isView(b)) {
    if (a.constructor !== b.constructor) return false;
    const bytesA = new Uint8Array(a.buffer, a.byteOffset, a.byteLength);
    const bytesB = new Uint8Array(b.buffer, b.byteOffset, b.byteLength);
    if (bytesA.length !== bytesB.length) return false;
    for (let i = 0; i < bytesA.length; i++) {
      if (bytesA[i] !== bytesB[i]) return false;
    }
    return true;
  }

  if (a instanceof ArrayBuffer && b instanceof ArrayBuffer) {
    if (a.byteLength !== b.byteLength) return false;
    const bytesA = new Uint8Array(a);
    const bytesB = new Uint8Array(b);
    for (let i = 0; i < bytesA.length; i++) {
      if (bytesA[i] !== bytesB[i]) return false;
    }
    return true;
  }

  if (a instanceof Map && b instanceof Map) {
    if (a.size !== b.size) return false;
    for (const [key, val] of a) {
      if (!b.has(key)) return false;
      if (!deepStrictEqualInner(val, b.get(key), seen)) return false;
    }
    return true;
  }

  if (a instanceof Set && b instanceof Set) {
    if (a.size !== b.size) return false;
    for (const item of a) {
      let found = false;
      for (const other of b) {
        if (deepStrictEqualInner(item, other, seen)) {
          found = true;
          break;
        }
      }
      if (!found) return false;
    }
    return true;
  }

  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepStrictEqualInner(a[i], b[i], seen)) return false;
    }
    return true;
  }
  if (Array.isArray(a) !== Array.isArray(b)) return false;

  const protoA = Object.getPrototypeOf(a);
  const protoB = Object.getPrototypeOf(b);
  if (protoA !== protoB) return false;

  const keysA = Reflect.ownKeys(objA);
  const keysB = Reflect.ownKeys(objB);
  if (keysA.length !== keysB.length) return false;

  for (const key of keysA) {
    if (!Object.prototype.hasOwnProperty.call(objB, key)) return false;
    if (
      !deepStrictEqualInner(
        (objA as Record<PropertyKey, unknown>)[key],
        (objB as Record<PropertyKey, unknown>)[key],
        seen,
      )
    ) {
      return false;
    }
  }
  return true;
}

export function isArray(val: unknown): val is unknown[] {
  return Array.isArray(val);
}
export function isBoolean(val: unknown): val is boolean {
  return typeof val === "boolean";
}
export function isNull(val: unknown): val is null {
  return val === null;
}
export function isNullOrUndefined(val: unknown): val is null | undefined {
  return val == null;
}
export function isNumber(val: unknown): val is number {
  return typeof val === "number";
}
export function isString(val: unknown): val is string {
  return typeof val === "string";
}
export function isUndefined(val: unknown): val is undefined {
  return val === undefined;
}
export function isRegExp(val: unknown): val is RegExp {
  return val instanceof RegExp;
}
export function isObject(val: unknown): val is object {
  return typeof val === "object" && val !== null;
}
export function isDate(val: unknown): val is Date {
  return val instanceof Date;
}
export function isError(val: unknown): val is Error {
  return val instanceof Error;
}
export function isFunction(val: unknown): val is Function {
  return typeof val === "function";
}
export function isPrimitive(val: unknown): boolean {
  return val === null || (typeof val !== "object" && typeof val !== "function");
}
export function isBuffer(val: unknown): boolean {
  return Buffer.isBuffer(val);
}
export function isPromise(val: unknown): val is Promise<unknown> {
  return (
    typeof val === "object" &&
    val !== null &&
    typeof (val as Promise<unknown>).then === "function"
  );
}

// returns a logger when NODE_DEBUG includes the given section
export function debuglog(section: string): (...args: unknown[]) => void {
  const envDebug =
    (typeof process !== "undefined" && process.env?.NODE_DEBUG) || "";
  const active = envDebug.toLowerCase().includes(section.toLowerCase());

  if (active) {
    return (...args: unknown[]) => {
      console.error(`${section.toUpperCase()} ${process?.pid || 0}:`, ...args);
    };
  }
  return () => {};
}

export const debug = debuglog;

export function stripVTControlCharacters(text: string): string {
  // eslint-disable-next-line no-control-regex
  return text.replace(
    /\x1B\[[0-9;]*[a-zA-Z]|\x1B\].*?(\x07|\x1B\\)|\x1B[()][A-Z0-9]|\x1B[#=]|\x1B./g,
    "",
  );
}

function isTypedArray(val: unknown): val is ArrayBufferView {
  return ArrayBuffer.isView(val) && !(val instanceof DataView);
}

function isUint8Array(val: unknown): val is Uint8Array {
  return val instanceof Uint8Array;
}

function isArrayBuffer(val: unknown): val is ArrayBuffer {
  return val instanceof ArrayBuffer;
}

function isDataView(val: unknown): val is DataView {
  return val instanceof DataView;
}

function isAnyArrayBuffer(val: unknown): boolean {
  return (
    val instanceof ArrayBuffer ||
    (typeof SharedArrayBuffer !== "undefined" && val instanceof SharedArrayBuffer)
  );
}

function isMap(val: unknown): val is Map<unknown, unknown> {
  return val instanceof Map;
}

function isSet(val: unknown): val is Set<unknown> {
  return val instanceof Set;
}

function isBooleanObject(val: unknown): boolean {
  return (
    typeof val === "object" &&
    val !== null &&
    Object.prototype.toString.call(val) === "[object Boolean]"
  );
}

function isNumberObject(val: unknown): boolean {
  return (
    typeof val === "object" &&
    val !== null &&
    Object.prototype.toString.call(val) === "[object Number]"
  );
}

function isStringObject(val: unknown): boolean {
  return (
    typeof val === "object" &&
    val !== null &&
    Object.prototype.toString.call(val) === "[object String]"
  );
}

function isSymbolObject(val: unknown): boolean {
  return (
    typeof val === "object" &&
    val !== null &&
    Object.prototype.toString.call(val) === "[object Symbol]"
  );
}

function isBoxedPrimitive(val: unknown): boolean {
  return (
    isBooleanObject(val) ||
    isNumberObject(val) ||
    isStringObject(val) ||
    isSymbolObject(val) ||
    (typeof val === "object" &&
      val !== null &&
      Object.prototype.toString.call(val) === "[object BigInt]")
  );
}

function isAsyncFunction(val: unknown): boolean {
  return Object.prototype.toString.call(val) === "[object AsyncFunction]";
}

function isGeneratorFunction(val: unknown): boolean {
  return Object.prototype.toString.call(val) === "[object GeneratorFunction]";
}

function isGeneratorObject(val: unknown): boolean {
  return Object.prototype.toString.call(val) === "[object Generator]";
}

function isNativeError(val: unknown): val is Error {
  return (
    val instanceof Error ||
    (typeof val === "object" &&
      val !== null &&
      Object.prototype.toString.call(val).endsWith("Error]"))
  );
}

function isProxy(val: unknown): boolean {
  try {
    // Best-effort: only detectable via Proxy revocable / no reliable runtime check.
    // Match Node's util.types.isProxy when unavailable by returning false.
    void val;
    return false;
  } catch {
    return false;
  }
}

export const types = {
  isDate,
  isRegExp,
  isNativeError,
  isError: isNativeError,
  isMap,
  isSet,
  isPromise,
  isTypedArray,
  isUint8Array,
  isArrayBuffer,
  isDataView,
  isAnyArrayBuffer,
  isBoxedPrimitive,
  isBooleanObject,
  isNumberObject,
  isStringObject,
  isSymbolObject,
  isAsyncFunction,
  isGeneratorFunction,
  isGeneratorObject,
  isProxy,
  isBuffer,
};

// styleText (Node.js 21.7+)

const ANSI_STYLES: Record<string, [number, number]> = {
  // Modifiers
  reset: [0, 0],
  bold: [1, 22],
  dim: [2, 22],
  italic: [3, 23],
  underline: [4, 24],
  inverse: [7, 27],
  hidden: [8, 28],
  strikethrough: [9, 29],
  // Foreground colors
  black: [30, 39],
  red: [31, 39],
  green: [32, 39],
  yellow: [33, 39],
  blue: [34, 39],
  magenta: [35, 39],
  cyan: [36, 39],
  white: [37, 39],
  gray: [90, 39],
  grey: [90, 39],
  blackBright: [90, 39],
  redBright: [91, 39],
  greenBright: [92, 39],
  yellowBright: [93, 39],
  blueBright: [94, 39],
  magentaBright: [95, 39],
  cyanBright: [96, 39],
  whiteBright: [97, 39],
  // Background colors
  bgBlack: [40, 49],
  bgRed: [41, 49],
  bgGreen: [42, 49],
  bgYellow: [43, 49],
  bgBlue: [44, 49],
  bgMagenta: [45, 49],
  bgCyan: [46, 49],
  bgWhite: [47, 49],
  bgBlackBright: [100, 49],
  bgRedBright: [101, 49],
  bgGreenBright: [102, 49],
  bgYellowBright: [103, 49],
  bgBlueBright: [104, 49],
  bgMagentaBright: [105, 49],
  bgCyanBright: [106, 49],
  bgWhiteBright: [107, 49],
};

export function styleText(format: string | string[], text: string): string {
  const formats = Array.isArray(format) ? format : [format];
  let result = text;
  for (const f of formats) {
    const style = ANSI_STYLES[f];
    if (style) {
      result = `\x1b[${style[0]}m${result}\x1b[${style[1]}m`;
    }
  }
  return result;
}

// parseArgs (Node.js 18.3+)

interface ParseArgsOptionConfig {
  type: "string" | "boolean";
  short?: string;
  multiple?: boolean;
  default?: string | boolean | string[] | boolean[];
}

interface ParseArgsConfig {
  args?: string[];
  options?: Record<string, ParseArgsOptionConfig>;
  strict?: boolean;
  allowPositionals?: boolean;
  tokens?: boolean;
}

interface ParseArgsResult {
  values: Record<string, string | boolean | (string | boolean)[] | undefined>;
  positionals: string[];
  tokens?: Array<{
    kind: string;
    name?: string;
    value?: string | boolean;
    index: number;
  }>;
}

export function parseArgs(config?: ParseArgsConfig): ParseArgsResult {
  const args =
    config?.args ??
    (typeof process !== "undefined" ? process.argv.slice(2) : []);
  const optDefs = config?.options ?? {};
  const allowPositionals = config?.allowPositionals ?? !config?.options;
  const strict = config?.strict ?? true;
  const wantTokens = config?.tokens ?? false;

  // Build short → long name map
  const shortMap: Record<string, string> = {};
  for (const [name, def] of Object.entries(optDefs)) {
    if (def.short) shortMap[def.short] = name;
  }

  const values: Record<
    string,
    string | boolean | (string | boolean)[] | undefined
  > = {};
  const positionals: string[] = [];
  const tokens: Array<{
    kind: string;
    name?: string;
    value?: string | boolean;
    index: number;
  }> = [];

  // Initialize defaults
  for (const [name, def] of Object.entries(optDefs)) {
    if (def.default !== undefined) {
      values[name] = def.default;
    }
  }

  let i = 0;
  let afterDash = false;
  while (i < args.length) {
    const arg = args[i];

    if (afterDash || !arg.startsWith("-") || arg === "-") {
      if (!allowPositionals && strict && !afterDash) {
        throw new Error(`Unexpected argument '${arg}'`);
      }
      positionals.push(arg);
      if (wantTokens) tokens.push({ kind: "positional", value: arg, index: i });
      i++;
      continue;
    }

    if (arg === "--") {
      afterDash = true;
      if (wantTokens) tokens.push({ kind: "option-terminator", index: i });
      i++;
      continue;
    }

    // --long or --long=value
    if (arg.startsWith("--")) {
      const eqIdx = arg.indexOf("=");
      const rawName = eqIdx !== -1 ? arg.slice(2, eqIdx) : arg.slice(2);
      const def = optDefs[rawName];

      if (!def && strict) {
        throw new Error(`Unknown option '--${rawName}'`);
      }

      const type = def?.type ?? "boolean";
      let val: string | boolean;

      if (type === "boolean") {
        val = eqIdx !== -1 ? arg.slice(eqIdx + 1) !== "false" : true;
      } else {
        if (eqIdx !== -1) {
          val = arg.slice(eqIdx + 1);
        } else if (i + 1 < args.length) {
          val = args[++i];
        } else {
          throw new Error(`Option '--${rawName}' requires a value`);
        }
      }

      if (def?.multiple) {
        const arr = (values[rawName] as (string | boolean)[] | undefined) ?? [];
        arr.push(val);
        values[rawName] = arr;
      } else {
        values[rawName] = val;
      }

      if (wantTokens)
        tokens.push({ kind: "option", name: rawName, value: val, index: i });
      i++;
      continue;
    }

    // -s (short options)
    if (arg.startsWith("-") && arg.length > 1) {
      // Handle combined short flags: -abc → -a -b -c
      const chars = arg.slice(1);
      for (let c = 0; c < chars.length; c++) {
        const ch = chars[c];
        const longName = shortMap[ch];

        if (!longName && strict) {
          throw new Error(`Unknown option '-${ch}'`);
        }

        const name = longName ?? ch;
        const def = longName ? optDefs[longName] : undefined;
        const type = def?.type ?? "boolean";

        let val: string | boolean;
        if (type === "boolean") {
          val = true;
        } else {
          // Rest of chars is the value, or next arg
          const rest = chars.slice(c + 1);
          if (rest.length > 0) {
            val = rest;
            c = chars.length; // break inner loop
          } else if (i + 1 < args.length) {
            val = args[++i];
          } else {
            throw new Error(`Option '-${ch}' requires a value`);
          }
        }

        if (def?.multiple) {
          const arr = (values[name] as (string | boolean)[] | undefined) ?? [];
          arr.push(val);
          values[name] = arr;
        } else {
          values[name] = val;
        }

        if (wantTokens)
          tokens.push({ kind: "option", name, value: val, index: i });
      }
      i++;
      continue;
    }

    i++;
  }

  const result: ParseArgsResult = { values, positionals };
  if (wantTokens) result.tokens = tokens;
  return result;
}

// toUSVString (Node.js 16.8+)

/**
 * Replaces lone surrogates with U+FFFD, yielding a well-formed Unicode string.
 *
 * Written as an explicit code-unit walk rather than a regex with lookbehind: lookbehind is a
 * relatively recent regex feature and this file is bundled and shipped to whatever browser the pod
 * runs in. A parser that throws at parse time takes the whole module with it.
 */
export function toUSVString(value: unknown): string {
  const str = String(value);
  let result = "";

  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);

    if (code >= 0xd800 && code <= 0xdbff) {
      // High surrogate: only valid when followed by a low surrogate.
      const next = str.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        result += str[i] + str[i + 1];
        i++;
      } else {
        result += "\uFFFD";
      }
    } else if (code >= 0xdc00 && code <= 0xdfff) {
      // Low surrogate with no high surrogate before it.
      result += "\uFFFD";
    } else {
      result += str[i];
    }
  }

  return result;
}

// MIMEType / MIMEParams (Node.js 16.7+)

const MIME_TOKEN = /^[!#$%&'*+\-.^_`|~A-Za-z0-9]+$/;

/**
 * 🔴 ASCII space/tab ONLY — never `String.prototype.trim()`.
 *
 * JS `trim()` also strips U+FEFF (BOM), U+00A0 (NBSP) and U+2028; Node's `.env` parser treats none of
 * them as whitespace. A BOM-prefixed `.env` — the ordinary Windows-editor case — therefore had its
 * FIRST KEY silently renamed from `﻿DB_URL` to `DB_URL`, or vice versa, with no error anywhere.
 */
function trimAsciiWhitespace(value: string): string {
  let start = 0;
  let end = value.length;

  while (start < end && (value[start] === " " || value[start] === "\t")) start++;
  while (end > start && (value[end - 1] === " " || value[end - 1] === "\t")) end--;

  return value.slice(start, end);
}

/**
 * Space, tab, newline and carriage return — Node's whitespace set for these parsers.
 *
 * ⚠️ Deliberately NOT `\f` or `\v`, which JS `trim()` also strips: `new MIMEType('text/plain\f')`
 * THROWS in Node, and a `trim()` here manufactured a valid MIME type out of input Node rejects.
 */
function isAsciiSpace(c: string): boolean {
  return c === " " || c === "\t" || c === "\n" || c === "\r";
}

/** Used to trim the whole `.env` input once, before scanning. */
function trimAsciiWhitespaceAndNewlines(value: string): string {
  let start = 0;
  let end = value.length;

  while (start < end && isAsciiSpace(value[start])) start++;
  while (end > start && isAsciiSpace(value[end - 1])) end--;

  return value.slice(start, end);
}

/**
 * The code points Node permits in a MIME parameter VALUE: tab, printable ASCII, and 0x80–0xFF.
 *
 * A parameter whose value contains anything else is DROPPED, not escaped — `a/b;x=\v` is `a/b` in
 * Node, where this used to keep the parameter and re-quote the control character back out of
 * `toString()`. It is a code-point RANGE, not a whitespace rule: NBSP (0xA0) and `é` (0xE9) are
 * inside it and are correctly kept, while `\v`, `\f`, NUL, DEL, BOM and anything above 0xFF are not.
 */
function isValidMimeParamValue(value: string): boolean {
  for (let i = 0; i < value.length; i++) {
    const code = value.charCodeAt(i);
    const allowed =
      code === 0x09 || (code >= 0x20 && code <= 0x7e) || (code >= 0x80 && code <= 0xff);

    if (!allowed) return false;
  }

  return true;
}

/** Trailing half — MIME subtypes and parameter values keep their LEADING whitespace. */
function trimTrailingAsciiWhitespace(value: string): string {
  let end = value.length;
  while (end > 0 && isAsciiSpace(value[end - 1])) end--;
  return value.slice(0, end);
}

/**
 * The parameter bag behind `MIMEType#params`. Node exposes it as a Map-alike, not a Map.
 *
 * ⚠️ CASE-SENSITIVE, and that is not an oversight. Lowercasing here looked like a tidy place to
 * normalise and had three silent consequences: `set('Charset', x)` then `get('charset')` INVENTED a
 * hit where Node returns `null`; `delete('CHARSET')` silently removed a parameter Node would keep;
 * and `toString()` renamed the caller's parameter. The lowercasing belongs in the MIMEType PARSER,
 * which is the only place a wire format defines it — not in the container.
 */
export class MIMEParams {
  #data = new Map<string, string>();

  delete(name: string): void {
    this.#data.delete(String(name));
  }

  get(name: string): string | null {
    const value = this.#data.get(String(name));
    return value === undefined ? null : value;
  }

  has(name: string): boolean {
    return this.#data.has(String(name));
  }

  set(name: string, value: string): void {
    const key = String(name);
    if (!MIME_TOKEN.test(key)) {
      throw new TypeError(`Invalid MIME parameter name: ${name}`);
    }

    /*
     * 🔴 The VALUE is validated too, with the same predicate the constructor uses. Checking only the
     * name let a CR/LF straight through and quoted it into the output:
     *
     *   params.set('boundary', '----X\r\nInjected: 1')
     *     → 'multipart/form-data;boundary="----X\r\nInjected: 1"'
     *
     * which BOTH Node's parser and this file's own `MIMEType` re-parse back to bare
     * `multipart/form-data` — the boundary silently gone. That is the identical lost-`boundary`
     * failure fixed on the PARSE side (obs-fold), reappearing on the SERIALIZE side, and setting
     * `boundary`/`filename`/`name` from a variable is the ordinary use of this API.
     *
     * Node throws `ERR_INVALID_MIME_SYNTAX` here; throwing is right for a setter (unlike
     * `formatWithOptions`, nothing is mid-log and the caller can still be told).
     */
    const text = String(value);
    if (!isValidMimeParamValue(text)) {
      throw new TypeError(`Invalid MIME parameter value: ${value}`);
    }

    this.#data.set(key, text);
  }

  entries(): IterableIterator<[string, string]> {
    return this.#data.entries();
  }

  keys(): IterableIterator<string> {
    return this.#data.keys();
  }

  values(): IterableIterator<string> {
    return this.#data.values();
  }

  [Symbol.iterator](): IterableIterator<[string, string]> {
    return this.#data.entries();
  }

  toString(): string {
    let out = "";
    for (const [key, value] of this.#data) {
      // A value that is not a bare token has to be quoted, or the result does not re-parse.
      const needsQuotes = value === "" || !MIME_TOKEN.test(value);
      const encoded = needsQuotes
        ? `"${value.replace(/["\\]/g, (c) => `\\${c}`)}"`
        : value;
      out += `${out ? ";" : ""}${key}=${encoded}`;
    }
    return out;
  }
}

/**
 * `util.MIMEType` — a parsed `type/subtype;params` value.
 *
 * Matches Node's normalisation: type, subtype and parameter NAMES are lowercased while parameter
 * VALUES keep their case (`TEXT/HTML; Foo=Bar` → `text/html;foo=Bar`).
 */
export class MIMEType {
  #type: string;
  #subtype: string;
  #params = new MIMEParams();

  constructor(input: string) {
    /*
     * 🔴 LEADING whitespace is skipped, and the whole string is NOT trimmed.
     *
     * `String(input).trim()` was wrong twice over, and both ways were silent. It stripped BOM, NBSP,
     * `\f` and `\v` — none of which Node treats as whitespace — so `'﻿text/plain'` and
     * `'text/plain\f'`, which Node REJECTS, were manufactured into a valid `text/plain`. And trimming
     * the TAIL corrupted an unterminated quoted parameter: Node reads `text/plain;z="a ` as `z="a "`,
     * keeping the space, because the trailing whitespace belongs to the parameter, not the string.
     * Trailing whitespace on the SUBTYPE is handled where the subtype is parsed, which is the only
     * place it is actually whitespace.
     */
    const raw = String(input);
    let lead = 0;
    while (lead < raw.length && isAsciiSpace(raw[lead])) lead++;

    const str = raw.slice(lead);
    const slash = str.indexOf("/");

    if (slash === -1) {
      throw new TypeError(`Invalid MIME type: ${input}`);
    }

    const type = str.slice(0, slash).toLowerCase();
    let rest = str.slice(slash + 1);

    let subtype = rest;
    const semi = rest.indexOf(";");
    if (semi !== -1) {
      subtype = rest.slice(0, semi);
      rest = rest.slice(semi + 1);
    } else {
      rest = "";
    }
    /*
     * TRAILING whitespace only. `text/plain  ; a=b` is valid (the space sits before the `;`), but
     * `text/ plain` is NOT a MIME type at all and Node throws — a full `.trim()` accepted it and
     * silently invented `text/plain` from malformed input.
     */
    subtype = trimTrailingAsciiWhitespace(subtype).toLowerCase();

    if (!MIME_TOKEN.test(type) || !MIME_TOKEN.test(subtype)) {
      throw new TypeError(`Invalid MIME type: ${input}`);
    }

    this.#type = type;
    this.#subtype = subtype;

    /*
     * 🔴 A scanner, NOT `rest.split(";")`. Splitting on `;` first truncates any QUOTED value that
     * contains one — `a="b;c"` came back as `b` — which is ordinary `Content-Disposition` and
     * multipart-boundary territory, and it produced a plausible wrong answer with no error.
     */
    let p = 0;

    while (p < rest.length) {
      /*
       * 🔴 `isAsciiSpace`, not an inlined `" " | "\t"`. The narrower set silently DROPPED every
       * parameter after a `\n` or `\r`: `multipart/form-data;\r\n boundary=----X` came back with NO
       * boundary and no error. That is RFC 7230 obs-fold — the literal wire form of a folded HTTP
       * header — and the parameters it eats are `charset` and `boundary`.
       *
       * The helper right above already documented the correct set; inlining a different one here made
       * the file contradict itself. (`\f` and `\v` are correctly excluded — Node rejects those.)
       */
      while (p < rest.length && (rest[p] === ";" || isAsciiSpace(rest[p]))) {
        p++;
      }
      if (p >= rest.length) break;

      const nameStart = p;
      while (p < rest.length && rest[p] !== "=" && rest[p] !== ";") p++;

      // A chunk with no `=` is not a parameter.
      if (p >= rest.length || rest[p] === ";") continue;

      /*
       * NOT trimmed: leading whitespace was already skipped, so anything left is TRAILING whitespace
       * before the `=`, which makes the name a non-token. Node drops `a  =  b` entirely — trimming
       * here would silently resurrect it.
       */
      const name = rest.slice(nameStart, p).toLowerCase();
      p++; // consume '='

      let value = "";
      let wasQuoted = false;

      if (rest[p] === '"') {
        wasQuoted = true;
        p++;

        while (p < rest.length) {
          if (rest[p] === "\\" && p + 1 < rest.length) {
            value += rest[p + 1];
            p += 2;
            continue;
          }
          if (rest[p] === '"') {
            p++;
            break;
          }
          value += rest[p++];
        }

        /*
         * 🔴 After a closing quote Node skips exactly ONE character and resumes parsing parameters —
         * it does NOT discard to the next `;`. Discarding silently LOST a whole parameter:
         * `a/b;x="v"ab=cd;e=f` is `a/b;x=v;b=cd;e=f` in Node (the `a` is the one skipped character
         * and `b=cd` survives), where this used to drop `b=cd` entirely and emit `a/b;x=v;e=f`.
         *
         * Landing on a `;` is fine — the separator skip at the top of the loop handles it.
         */
        p++;
      } else {
        const valueStart = p;
        while (p < rest.length && rest[p] !== ";") p++;
        /*
         * LEADING whitespace is kept, TRAILING is trimmed — Node keeps `a= b` as `" b"` but reads
         * `a=v\t` as `v`. Getting only half of that rule wrong is invisible: the value merely gains a
         * tab and `toString()` then quotes it, so `x=v` silently becomes `x="v\t"`.
         */
        value = trimTrailingAsciiWhitespace(rest.slice(valueStart, p));
      }

      /*
       * FIRST-wins on a duplicate, and an empty UNQUOTED value is DROPPED (an explicitly quoted
       * `a=""` is KEPT). All three were silently the opposite here. Last-wins is the more natural
       * thing to write and gives the opposite answer with no error: `text/plain; a=b; a=c` keeps `a=b`.
       */
      if (
        MIME_TOKEN.test(name) &&
        (value !== "" || wasQuoted) &&
        isValidMimeParamValue(value) &&
        !this.#params.has(name)
      ) {
        this.#params.set(name, value);
      }
    }
  }

  get type(): string {
    return this.#type;
  }

  set type(value: string) {
    const next = String(value).toLowerCase();
    if (!MIME_TOKEN.test(next)) {
      throw new TypeError(`Invalid MIME type: ${value}`);
    }
    this.#type = next;
  }

  get subtype(): string {
    return this.#subtype;
  }

  set subtype(value: string) {
    const next = String(value).toLowerCase();
    if (!MIME_TOKEN.test(next)) {
      throw new TypeError(`Invalid MIME subtype: ${value}`);
    }
    this.#subtype = next;
  }

  get essence(): string {
    return `${this.#type}/${this.#subtype}`;
  }

  get params(): MIMEParams {
    return this.#params;
  }

  toString(): string {
    const params = this.#params.toString();
    return params ? `${this.essence};${params}` : this.essence;
  }

  toJSON(): string {
    return this.toString();
  }
}

// AbortSignal helpers (Node.js 19+)

/**
 * `util.aborted(signal, resource)` — a promise that settles when `signal` aborts. Never rejects.
 *
 * ⚠️ Node holds a WEAK reference to `resource` so an un-aborted signal cannot leak the resource.
 * `WeakRef` exists in browsers, but the listener itself is what retains memory here, so the
 * parameter is accepted and unused — documented rather than silently dropped.
 */
export function aborted(signal: AbortSignal, resource?: unknown): Promise<void> {
  void resource;

  if (!signal || typeof signal.addEventListener !== "function") {
    throw new TypeError("aborted(signal, resource): signal must be an AbortSignal");
  }

  if (signal.aborted) return Promise.resolve();

  return new Promise<void>((resolve) => {
    signal.addEventListener("abort", () => resolve(), { once: true });
  });
}

/**
 * ⚠️ DEGRADED, deliberately. In Node these mark an AbortSignal as transferable across a
 * `postMessage` boundary. The browser has no such capability — an `AbortSignal` is not structured-
 * cloneable — so these return a perfectly ordinary controller/signal that simply is not transferable.
 *
 * Aborting still works; only cross-worker transfer does not. Returning a WORKING object is the honest
 * choice over throwing: a build tool that calls this to obtain a controller gets one.
 */
export function transferableAbortController(): AbortController {
  return new AbortController();
}

/** ⚠️ DEGRADED — see `transferableAbortController`. Returns the signal unchanged. */
export function transferableAbortSignal(signal: AbortSignal): AbortSignal {
  return signal;
}

